function createCounter(start = 0) {
  let count = start;          // captured by the closures below
  return {
    increment: () => ++count,
    current: () => count,
  };
}

const a = createCounter();
const b = createCounter(10);
a.increment();
a.increment();
console.log(a.current()); // 2
console.log(b.current()); // 10
console.log(a.count);     // undefined: count is private

