function createAccount(initial) {
  let balance = initial;
  const history = [];
  return {
    deposit(amount) {
      if (!(amount > 0)) return 'invalid amount';
      balance += amount;
      history.push('+' + amount);
      return null;
    },
    withdraw(amount) {
      if (!(amount > 0)) return 'invalid amount';
      if (amount > balance) return 'insufficient funds';
      balance -= amount;
      history.push('-' + amount);
      return null;
    },
    getBalance: () => balance,
    getHistory: () => history.slice(),
  };
}

const accounts = new Map();
for (const raw of stdin.split('\n')) {
  const line = raw.trim();
  if (!line) continue;
  const [cmd, name, value] = line.split(/\s+/);
  const amount = Number(value);
  if (cmd === 'open') {
    if (accounts.has(name)) console.log(name + ': already exists');
    else accounts.set(name, createAccount(amount));
    continue;
  }
  const acct = accounts.get(name);
  if (!acct) { console.log(name + ': unknown account'); continue; }
  let error = null;
  if (cmd === 'deposit') error = acct.deposit(amount);
  else if (cmd === 'withdraw') error = acct.withdraw(amount);
  else if (cmd === 'balance') console.log(name + ': ' + acct.getBalance());
  else if (cmd === 'history') {
    const h = acct.getHistory();
    console.log(name + ': ' + (h.length ? h.join(' ') : 'no transactions'));
  }
  if (error) console.log(name + ': ' + error);
}

